type primeCallbackNode = Constructor_Test_Primes_Cons[int64]
var primeCallbackSink int64
func primeGeneratedCallback(n int64) int64 {return Call_Test_Primes_sumList(Call_Test_Primes_sieve(Call_Test_Primes_go__range(2,n)))}
func primeNativeCallbackFilter(p func(int64)bool, input *primeCallbackNode) *primeCallbackNode {
 var output,tail *primeCallbackNode
 for cursor:=input; cursor!=nil; cursor=cursor.V1 {
  if p(cursor.V0) {
   node:=&primeCallbackNode{Rc:1,V0:cursor.V0}
   if output==nil {output=node} else {tail.V1=node};tail=node
  }
 }
 return output
}
func primeNativeCallbackSieve(input *primeCallbackNode) *primeCallbackNode {
 if input==nil{return nil};p:=input.V0
 return &primeCallbackNode{Rc:1,V0:p,V1:primeNativeCallbackSieve(primeNativeCallbackFilter(func(x int64)bool{return rt.IntMod(x,p)!=0},input.V1))}
}
func primeInlineCallbackSieve(input *primeCallbackNode) *primeCallbackNode {
 if input==nil{return nil};p:=input.V0
 var output,tail *primeCallbackNode
 for cursor:=input.V1;cursor!=nil;cursor=cursor.V1 {
  if rt.IntMod(cursor.V0,p)!=0 {
   node:=&primeCallbackNode{Rc:1,V0:cursor.V0}
   if output==nil {output=node} else {tail.V1=node};tail=node
  }
 }
 return &primeCallbackNode{Rc:1,V0:p,V1:primeInlineCallbackSieve(output)}
}
func primeIndependentOracle(n int64) int64 {
 var total int64
 for i:=int64(2);i<=n;i++ {prime:=true;for d:=int64(2);d*d<=i;d++ {if i%d==0 {prime=false;break}};if prime{total+=i}}
 return total
}
func TestPrimeCallbacksOracle(t *testing.T) {
 for n:=int64(-4);n<=600;n++ {
  want:=primeIndependentOracle(n)
  for _,fn:=range []func(*primeCallbackNode)*primeCallbackNode{Call_Test_Primes_sieve,primeNativeCallbackSieve,primeInlineCallbackSieve} {
   if got:=Call_Test_Primes_sumList(fn(Call_Test_Primes_go__range(2,n)));got!=want {t.Fatalf("n=%d got=%d want=%d",n,got,want)}
  }
 }
}
