func BenchmarkPrimeCallbackInline(b *testing.B){b.ReportAllocs();for i:=0;i<b.N;i++ {primeCallbackSink=Call_Test_Primes_sumList(primeInlineCallbackSieve(Call_Test_Primes_go__range(2,500)))}}
